ne}.screen{display:none;min-height:calc(100vh - 89px);padding-top:32px}.screen.active{display:block}.garage-grid{display:grid;grid-template-columns:minmax(260px,28%) 1fr;gap:4.7%;min-height:calc(100vh - 171px)}.garage-aside{padding:42px 0 20px;display:flex;flex-direction:column;align-items:flex-start}.eyebrow{font-size:9px;letter-spacing:1.6px;color:#96969c;font-weight:700;display:flex;align-items:center;gap:8px}.live-dot{height:6px;width:6px;background:var(--acid);border-radius:50%;box-shadow:0 0 9px #d5ff3f99}.garage-aside h1,.section-heading h2,.race-top h2{font:900 clamp(48px,6.1vw,86px)/.85 var(--display);letter-spacing:-1px;margin:26px 0 16px}.garage-aside h1 em,.section-heading h2 em,.race-top h2 em{font-style:normal;color:var(--acid)}.lead{max-width:285px;color:#85858b;font-size:12px;line-height:1.8;margin:0 0 31px}.car-selector{width:100%;display:flex;flex-direction:column;gap:5px}.car-choice{width:100%;display:grid;grid-template-columns:37px 1fr auto;align-items:center;text-align:left;background:transparent;padding:11px 12px;border:1px solid transparent;color:#83838a;transition:.2s}.car-choice:hover{background:#ffffff06;color:#eee}.car-choice.selected{background:#1b1c20;border-color:#34353a;color:#fff}.car-choice .car-num{font:700 12px var(--display);color:#66676e}.car-choice.selected .car-num{color:var(--acid)}.car-choice strong{font:700 12px var(--font);letter-spacing:.3px}.car-choice small{display:block;font-size:8px;color:#797980;margin-top:3px}.car-choice .arrow{font-size:17px;color:#76777d}.car-count{display:flex;align-items:center;width:100%;gap:10px;color:#75767d;font:700 10px var(--display);margin:18px 0 22px}.car-count #carIndex{font-size:17px;color:#fff}.count-line{height:1px;background:#42434a;flex:1}.count-label{font:600 8px var(--font);letter-spacing:1px;margin-left:4px}.button{background:none;border:1px solid #595b60;padding:14px 18px;font:800 10px var(--font);letter-spacing:1.3px;transition:.2s}.button span{font-size:17px;margin-left:17px}.button-primary{background:var(--acid);color:#161713;border-color:var(--acid)}.button-primary:hover{background:#e3ff79;transform:translateY(-2px);box-shadow:0 5px 25px #caff3630}.wide{width:100%;text-align:left;display:flex;justify-content:space-between;align-items:center;margin-top:auto}.wide span{font-size:18px}.showroom{position:relative;overflow:hidden;min-height:585px;background:linear-gradient(145deg,#191a1e 0%,#202125 48%,#151619 100%);isolation:isolate}.showroom-grid{position:absolute;inset:0;background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff08 1px,transparent 1px);background-size:50px 50px;transform:perspective(500px) rotateX(56deg) scale(1.7);transform-origin:bottom center;opacity:.34;mask-image:linear-gradient(transparent 10%,#000 85%)}.showroom-glow{position:absolute;width:60%;height:45%;left:18%;top:26%;background:#c9fa3517;filter:blur(70px);border-radius:50%}.showroom-meta{position:absolute;z-index:2;top:24px;left:26px;right:26px;display:flex;justify-content:space-between;color:#87888f;font-size:8px;letter-spacing:1.5px}.showroom canvas{position:absolute;z-index:2;width:100%;height:68%;left:0;top:16%;cursor:grab}.showroom canvas:active{cursor:grabbing}.showroom-floor{position:absolute;z-index:1;bottom:14%;left:9%;width:82%;height:11%;border-radius:50%;background:#0009;filter:blur(16px)}.car-title{position:absolute;z-index:3;left:7%;top:20%;display:flex;align-items:baseline;gap:8px;font:600 12px var(--display);letter-spacing:2px;color:#c4c5c9}.car-title strong{font:900 29px var(--display);letter-spacing:1px;color:#fff}.car-title .car-year{font-size:9px;color:#777}.car-specs{position:absolute;z-index:3;left:7%;right:7%;bottom:8%;display:grid;grid-template-columns:repeat(3,1fr);gap:8%}.car-specs small{display:block;color:#85868d;font-size:8px;letter-spacing:1.2px;margin-bottom:5px}.car-specs b{font:800 21px var(--display)}.car-specs b i{font:500 10px var(--font);font-style:normal;color:#a6a6aa}.spec-track{height:2px;background:#414247;margin-top:8px}.spec-track span{height:100%;display:block;background:var(--acid);width:55%;transition:width .3s}.rotate-hint{position:absolute;z-index:3;right:25px;top:47%;color:var(--acid);font-size:20px}.rotate-hint span{display:block;color:#85858b;font-size:7px;letter-spacing:1px;margin-top:6px}.bottom-strip{height:48px;display:flex;align-items:center;justify-content:space-between;color:#77787e;font-size:8px;letter-spacing:1.5px;border-top:1px solid #ffffff12}.bottom-strip b{color:var(--acid);padding:0 8px}.bottom-strip button{height:100%;background:none;color:#efeff0;font-size:9px;letter-spacing:1.2px}.bottom-strip button span{font-size:17px;color:var(--acid);margin-left:14px}
