solid #2d2e33}.tuning-total>span{display:block;color:#88898e;font-size:8px;letter-spacing:1.3px}.tuning-total strong{display:block;font:800 22px var(--display);margin:4px 0 10px}.tuning-total i{font:500 10px var(--font);font-style:normal;color:#97989d}.total-meter{height:3px;background:#3a3b40}.total-meter span{display:block;height:100%;width:35%;background:var(--acid);transition:width .4s}.tuning-shop{border:1px solid #2d2e33;background:#17181b;display:flex;flex-direction:column;min-width:0}.shop-top{padding:22px 24px 0}.shop-top h3{font:900 28px var(--display);letter-spacing:1.5px;margin:4px 0 17px}.shop-categories{display:flex;overflow:auto;gap:5px;border-bottom:1px solid #303136}.category{background:transparent;padding:11px 12px;color:#888990;font-size:9px;white-space:nowrap;letter-spacing:.4px;border-bottom:2px solid transparent;margin-bottom:-1px}.category.active{color:var(--acid);border-color:var(--acid)}.part-list{overflow-y:auto;max-height:430px;padding:4px 24px;flex:1}.part-card{display:grid;grid-template-columns:49px 1fr auto;align-items:center;gap:13px;padding:15px 0;border-bottom:1px solid #292a2f}.part-icon{height:47px;width:47px;background:#222329;display:grid;place-items:center;color:var(--acid);font-size:20px;position:relative}.part-icon:after{content:'';position:absolute;inset:6px;border:1px solid #ffffff0a}.part-copy strong{font:700 11px var(--font);display:block}.part-copy small{color:#888990;font-size:8px;display:block;margin-top:5px}.part-stats{display:flex;gap:8px;margin-top:8px}.part-stats span{font:700 9px var(--display);color:#b4ff53}.part-action{text-align:right}.part-action button{padding:9px 12px;min-width:89px;background:#25262b;border:1px solid #414248;color:#ddd;font-size:9px;font-weight:800;letter-spacing:.5px}.part-action button:hover{border-color:var(--acid);color:var(--acid)}.part-action button.owned{color:var(--acid);border-color:#657626;background:#20251a}.part-action button:disabled{opacity:.55;cursor:default}.part-action small