.race-screen{padding-top:18px;padding-bottom:30px}.race-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.race-top h2{font-size:42px;margin:7px 0 0}.race-track-picker{display:flex;gap:7px}.track-chip{padding:10px 12px;background:#1a1b1f;border:1px solid #303136;color:#8c8d93;font-size:8px;letter-spacing:.7px}.track-chip.active{border-color:var(--acid);color:var(--acid)}.race-stage{height:min(64vh,560px);min-height:390px;background:#121316;border:1px solid #33343a;position:relative;overflow:hidden}.race-stage canvas{position:absolute;width:100%;height:100%;inset:0}.race-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#0d0e10b8,transparent 28%,transparent 72%,#0d0e10a8),linear-gradient(0deg,#101114b0,transparent 36%,#10111490)}.race-hud{position:absolute;inset:20px 22px;display:flex;justify-content:space-between;pointer-events:none}.hud-position,.hud-speed,.hud-lap{align-self:flex-start;background:#111216b8;border:1px solid #ffffff22;padding:12px 14px;min-width:90px;backdrop-filter:blur(8px)}.hud-position small,.hud-lap small{display:block;color:#a3a4aa;font-size:8px;letter-spacing:1px}.hud-position strong{font:900 32px var(--display);color:var(--acid)}.hud-position strong span{font:600 14px var(--display);color:#aaa}.hud-speed{position:absolute;left:50%;top:0;transform:translateX(-50%);text-align:center;min-width:160px}.hud-speed>strong{font:900 49px/.9 var(--display);letter-spacing:2px}.hud-speed>span{font-size:8px;color:#a5a6ab;letter-spacing:1px;margin-left:4px}.hud-speed small{display:flex;justify-content:space-between;color:#999;font-size:8px;letter-spacing:1px;margin-top:7px}.hud-speed small b{color:var(--acid)}.rpm{height:3px;background:#444;margin-top:8px}.rpm span{display:block;height:100%;background:var(--acid);width:0}.hud-lap{margin-left:auto}.hud-lap strong{display:block;font:800 22px var(--display);margin:3px 0}.hud-lap i{font:500 10px var(--font);font-style:normal;color:#999}.race-progress{height:2px;background:#444;margin-top:8px;width:110px}.race-progress span{display:block;height:100%;width:0;background:var(--acid)}.race-message{position:absolute;top:40%;left:50%;transform:translate(-50%,-50%);font:900 72px var(--display);color:var(--acid);text-shadow:0 3px 20px #000;white-space:nowrap}.cinematic,.finish-panel{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;background:linear-gradient(#10111425,#101114b0);z-index:2;transition:opacity .5s}.cinematic-kicker{font-size:9px;letter-spacing:3px;color:var(--acid)}.cinematic strong{font:900 clamp(48px,8vw,95px)/.95 var(--display);margin:13px 0;letter-spacing:2px}.cinematic-sub{font-size:9px;color:#bbb;letter-spacing:2px;margin-bottom:25px}.cinematic .button{min-width:165px}.finish-panel{display:none;background:#101114d9}.finish-panel.show{display:flex}.finish-panel h3{font:900 62px var(--display);margin:12px}.prize{color:#aaa;font-size:12px}.prize strong{font:900 29px var(--display);color:var(--acid);margin:0 4px}.finish-panel p{font-size:12px;color:#a0a0a5;margin:6px 0 20px}.race-controls{height:70px;display:flex;align-items:center;justify-content:space-between}.control-help{font-size:9px;color:#777;display:flex;gap:8px;align-items:center}.control-help span{border:1px solid #3c3d42;padding:5px 7px;color:#c0c0c3;font:700 8px var(--font)}.race-utility{display:flex;gap:22px}.race-utility button{background:none;color:#909197;font-size:9px;letter-spacing:1px}.race-utility button:hover{color:var(--acid)}.touch-controls{display:none;gap:7px;align-items:center}.touch-controls button{touch-action:none;user-select:none}.steer{width:48px;height:48px;background:#222329;border:1px solid #414248;font:900 24px var(--display)}.pedal{width:63px;height:48px;background:#25262b;border:1px solid #414248;font:800 8px var(--font);letter-spacing:.7px}.pedal.gas{background:var(--acid);border-color:var(--acid);color:#141512}.mobile-nav{display:none}
/* install modal */
.install-scene{position:fixed;inset:0;background:#08090bec;z-index:20;display:none;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(8px)}.install-scene.show{display:flex}.install-card{width:min(610px,100%);background:#191a1e;border:1px solid #3b3c42;padding:20px 28px 25px;box-shadow:0 24px 100px #000b;animation:modalIn .4s both}.install-head{display:flex;justify-content:space-between;align-items:center}.install-head button{background:none;color:#aaa;font-size:25px}.install-visual{height:210px;position:relative;background:radial-gradient(ellipse,#35363c,#1b1c20 67%);overflow:hidden;margin:17px 0 13px}.engine-art{position:absolute;left:50%;top:52%;transform:translate(-50%,-50%);width:210px;height:124px;transition:.4s}.engine-core{position:absolute;left:48px;top:26px;width:118px;height:77px;background:linear-gradient(135deg,#999ba0,#41434a 35%,#24252a 65%,#777980);border:2px solid #aeb0b6;clip-path:polygon(12% 0,87% 0,100% 20%,95% 100%,5% 100%,0 22%);box-shadow:0 0 20px #d5ff3f22}.engine-core:before,.engine-core:after{content:'';position:absolute;width:70%;height:7px;left:15%;background:#17181c;top:17px;box-shadow:0 17px #17181c,0 34px #17181c}.engine-part{position:absolute;z-index:2;left:83px;top:3px;width:47px;height:35px;background:linear-gradient(140deg,#d5ff3f,#657b21);border:2px solid #f0ff9c;transform:rotate(-8deg);box-shadow:0 0 17px #d5ff3f77;transition:.5s}.bolt{position:absolute;z-index:3;width:7px;height:7px;border-radius:50%;background:#ddd;box-shadow:0 0 4px #fff}.b1{left:60px;top:39px}.b2{left:150px;top:39px}.b3{left:60px;top:89px}.b4{left:150px;top:89px}.wrench{position:absolute;z-index:4;font-size:27px;top:13px;left:16px;transform:rotate(-32deg);animation:wrench .8s infinite alternate}.hood{position:absolute;z-index:5;left:12px;right:12px;top:-80px;height:83px;border:2px solid #8e9098;background:linear-gradient(155deg,#41434b,#1a1b1e);color:#ccc;text-align:center;padding:15px;font:800 10px var(--font);letter-spacing:4px;transition:.6s transform}.install-beam{position:absolute;left:8%;right:8%;bottom:18px;height:1px;background:#d5ff3f66;box-shadow:0 0 20px #d5ff3f}.install-step{font-size:8px;color:var(--acid);letter-spacing:1.5px}.install-card h3{font:900 30px var(--display);margin:6px 0}.install-card p{color:#96979d;font-size:11px;margin:0 0 13px}.install-progress{height:2px;background:#3a3b40}.install-progress span{display:block;background:var(--acid);height:100%;width:0;transition:width .25s}.install-log{height:20px;color:#b1b1b5;font-size:8px;letter-spacing:.7px;margin-top:10px}.toast{position:fixed;z-index:30;bottom:28px;left:50%;transform:translate(-50%,20px);padding:12px 18px;background:var(--acid);color:#151612;font-size:10px;font-weight:800;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes wrench{to{transform:rotate(12deg) translate(5px,4px)}}@keyframes modalIn{from{opacity:0;transform:translateY(18px) scale(.98)}to{opacity:1;transform:none}}
@media(max-width:1050px){.app-shell{padding:0 3vw}.garage-grid{grid-template-columns:minmax(245px,31%) 1fr;gap:3%}.tuning-layout{grid-template-columns:38% 1fr}.part-list{padding:4px 16px}.shop-top{padding-left:16px;padding-right:16px}.car-specs{gap:4%}.garage-aside{padding-top:26px}}
